using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "CrystallizedMemoryOmenData", menuName = "Data/Battle/Omens System/Omen Data/Orion/CrystallizedMemory Omen Data")]
public class CrystallizedMemoryOmenData : OmenData
{
	[Header("Crystalyzed Memory Omen")]
	[SerializeField]
	private int purifyAmount;

	[SerializeField]
	private PurifyWithBadEffectAction purifyWithBadEffectAction;

	[SerializeField]
	private KarmicOrbStarAbility karmicOrbStarAbility;

	public int PurifyAmount => purifyAmount;

	public PurifyWithBadEffectAction PurifyWithBadEffectAction => purifyWithBadEffectAction;

	public override void Initialize(OmenInstance omenInstance)
	{
		ReferenceSingleton<OrionOmensHandler>.Instance.CrystallizedMemoryOmenActive = true;
	}

	public override void OmenRemoved()
	{
		ReferenceSingleton<OrionOmensHandler>.Instance.CrystallizedMemoryOmenActive = false;
	}

	public override string OmenConvertedDescription()
	{
		return Smart.Format(base.OmenConvertedDescription(), purifyAmount - karmicOrbStarAbility.ActionValue, purifyWithBadEffectAction.EffectAmount - 1);
	}
}
